 "content": "def transform(grid):
    """Recolor each 4-connected monochrome component containing a solid >=5x5 rectangle."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r0 in range(h):
        for c0 in range(w):
            if (r0, c0) in seen:
                continue
            color = grid[r0][c0]
            comp = {(r0, c0)}
            stack = [(r0, c0)]
            seen.add((r0, c0))
            while stack:
                r, c = stack.pop()
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        comp.add((nr, nc))
                        stack.append((nr, nc))
            if len(comp) < 25:
                continue
            rs = [r for r, _ in comp]
            cs = [c for _, c in comp]
            qualifies = False
            for top in range(min(rs), max(rs) - 3):
                if qualifies:
                    break
                for left in range(min(cs), max(cs) - 3):
                    if all((r, c) in comp for r in range(top, top + 5) for c in range(left, left + 5)):
                        qualifies = True
                        break
            if qualifies:
                for r, c in comp:
                    out[r][c] = 4
    return out
